import { randomUUID } from 'node:crypto';
import type { RequestHandler } from 'express';

const CLIENT_REQUEST_ID_PATTERN = /^[A-Za-z0-9._:-]{8,128}$/;

/**
 * Creates the middleware that assigns a correlation id to every request.
 * The id is always generated by the server (UUID), stored in `res.locals.requestId`
 * and returned in the `X-Request-Id` response header. An incoming `X-Request-Id`
 * is never echoed: if it matches `^[A-Za-z0-9._:-]{8,128}$` it is kept only as
 * `res.locals.clientRequestId`, for the access log.
 *
 * @returns Express middleware.
 */
export function requestId(): RequestHandler {
  return (req, res, next) => {
    const id = randomUUID();
    res.locals.requestId = id;
    const incoming = req.get('x-request-id');
    if (incoming !== undefined && CLIENT_REQUEST_ID_PATTERN.test(incoming)) {
      res.locals.clientRequestId = incoming;
    }
    res.setHeader('X-Request-Id', id);
    next();
  };
}
